def test_history_event_assertions_accept_valid_structured_response(refactor_repo):
    eid = "eid1_" + "11" * 32
    events = _expected_history_events(refactor_repo, eid)
    events[2]["flags"].append("signature_changed")
    _assert_history_events(events, refactor_repo, eid)


@pytest.mark.parametrize("corruption", (
    "previous_source_commit", "move_endpoints", "move_paths", "material", "diagnostic_only_sha",
    "event_order", "literal_names", "byte_bounds", "root_parent", "missing_source", "missing_span",
))
def test_history_event_assertions_reject_corrupted_responses(refactor_repo, corruption):
    eid = "eid1_" + "11" * 32
    events = _expected_history_events(refactor_repo, eid)
    if corruption == "previous_source_commit":
        events[1]["source"]["commit"]["hex"] = refactor_repo["commits"][1]
    elif corruption == "move_endpoints":
        events[3]["source"], events[3]["destination"] = events[3]["destination"], events[3]["source"]
    elif corruption == "move_paths":
        source, destination = events[3]["source"], events[3]["destination"]
        source["path_bytes_b64"], destination["path_bytes_b64"] = destination["path_bytes_b64"], source["path_bytes_b64"]
    elif corruption == "material":
        events[1]["material"] = False
    elif corruption == "diagnostic_only_sha":
        events[1]["diagnostic"] = refactor_repo["commits"][1]
        del events[1]["commit"]
    elif corruption == "event_order":
        events[1], events[4] = events[4], events[1]
    elif corruption == "literal_names":
        events[2]["source"]["names"] = ["check_token"]
    elif corruption == "byte_bounds":
        events[1]["destination"]["span"]["end_byte"] -= 1
    elif corruption == "root_parent":
        events[0]["parent"] = dict(events[0]["commit"])
    elif corruption == "missing_source":
        events[1]["source"] = None
    elif corruption == "missing_span":
        del events[1]["destination"]["span"]
    with pytest.raises(AssertionError):
        _assert_history_events(events, refactor_repo, eid)


def test_refactor_repo_manifest_matches_committed_git_bytes(refactor_repo):
    repo = refactor_repo["repo"]
    commits = refactor_repo["commits"]
    assert len(commits) == len(set(commits)) == 5
    assert tuple(_git_bytes(repo, "log", "--reverse", "--format=%H").decode("ascii").splitlines()) == commits
    assert tuple(_git_bytes(repo, "log", "--reverse", "--format=%s").decode("ascii").splitlines()) == refactor_repo["messages"]
    assert len(set(refactor_repo["messages"])) == 5
    assert refactor_repo["paths"] == ("auth.py", "auth.py", "auth.py", "security.py", "security.py")
    assert refactor_repo["names"] == (
        "validate_token", "validate_token", "check_token", "check_token", "check_token",
    )
    assert len(refactor_repo["sources"]) == 5
    for commit, path, name, source in zip(
        commits, refactor_repo["paths"], refactor_repo["names"], refactor_repo["sources"], strict=True,
    ):
        assert _git_bytes(repo, "show", f"{commit}:{path}") == source
        assert source.startswith(b"def " + name.encode("ascii") + b"(raw):\n")
    for commit in commits[3:]:
        assert _git_bytes(repo, "show", f"{commit}:auth.py") == b"# Token validation moved to security.py.\n"


def test_foundation_tracks_five_events_after_restart(refactor_repo):
    repo = refactor_repo["repo"]
    built = _index_cli(repo, "index", "--scope", "demo", "--ref", "HEAD", "--json")
    assert built.returncode == 0, (
        "Foundation acceptance remains RED: gita index is not implemented\n"
        f"exit={built.returncode}; stderr={built.stderr[:1200]}"
    )
    index_payload = _successful_payload(built)
    current = _successful_payload(_index_cli(repo, "id", "check_token", "--scope", "demo", "--json"))
    assert current["generation"] == index_payload["generation"]
    assert len(current["results"]) == 1
    entity_id = current["results"][0]["eid"]
    assert entity_id.startswith("eid1_")
    assert len(entity_id.removeprefix("eid1_")) == 64
    assert set(entity_id.removeprefix("eid1_")) <= set("0123456789abcdef")

    history = _successful_payload(_index_cli(
        repo, "history", entity_id, "--indexed", "--scope", "demo",
        "--order", "oldest", "--limit", "20", "--json",
    ))
    assert history["generation"] == current["generation"]
    _assert_history_events(history["results"], refactor_repo, entity_id)

    historical = _successful_payload(_index_cli(
        repo, "id", "validate_token", "--historical", "--scope", "demo", "--json",
    ))
    assert historical["generation"] == current["generation"]
    assert len(historical["results"]) == 1
    assert historical["results"][0]["eid"] == entity_id